import java.util.*;
import java.io.*;

public class Main {
    public static List<List<Integer>> combinationSum2(int[] candidates, int target) {
        Arrays.sort(candidates);
        List<List<Integer>> res = new ArrayList<>();
        backtrack(candidates, target, res, new ArrayList<>(), 0);
        return res;
    }

    private static void backtrack(int[] candidates, int target, List<List<Integer>> res, List<Integer> stack, int start) {
        if (target == 0) {
            res.add(new ArrayList<>(stack));
            return;
        }
        for (int i = start; i < candidates.length; i++) {
            if (i > start && candidates[i] == candidates[i-1]) continue;
            if (candidates[i] > target) break;
            stack.add(candidates[i]);
            backtrack(candidates, target - candidates[i], res, stack, i + 1);
            stack.remove(stack.size() - 1);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine(); if (line == null) return;
        int target = Integer.parseInt(br.readLine().trim());
        line = line.replace("[", "").replace("]", "").replace(",", " ").trim();
        if (line.isEmpty()) { System.out.println("[]"); return; }
        String[] parts = line.split("\\s+");
        int[] candidates = new int[parts.length];
        for (int i = 0; i < parts.length; i++) candidates[i] = Integer.parseInt(parts[i]);
        List<List<Integer>> res = combinationSum2(candidates, target);
        System.out.println(res);
    }
}

